llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib had an absolute oral bioavailability of 14.9% at 10 mg, below the 20% threshold; this is the highest-transfer direct human F measurement and strongly supports low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "9-Nitrocamptothecin was reported to have very low absolute oral bioavailability in patients, with high transferability; its lactone-rich, polar fused-ring character parallels the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hydroxysafflor yellow A showed low oral bioavailability in healthy volunteers after oral administration; its many hydroxyl groups and high polarity are relevant to the query's permeability limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Baicalin exhibited poor oral bioavailability in healthy subjects based on AUC comparison, supporting low F for a polar, poorly permeable natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Artemisinin has low oral bioavailability in humans in multiple reports; despite some variable or contradictory reports, the preponderance of artemisinin data is low and moderately transferable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Idarubicin had a median oral bioavailability of 29% in cancer patients, above the 20% threshold, but its low transfer score and different anthracycline/aminosugar scaffold limit applicability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Zidovudine showed 60-70% absolute oral bioavailability, but this nucleoside analogue has very low transferability to the query's polycyclic lactone system.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, rigid polycyclic lactone with very low predicted permeability. The most transferable experimental evidence—5-hydroxyrofecoxib (F≈14-15%), 9-nitrocamptothecin (very low), HSYA (low), baicalin (poor), and artemisinin (low)—consistently indicates F<20%. Contradictory high-F examples (zidovudine, idarubicin, retrorsine, doxifluridine, idarubicinol) have much lower transfer scores and structurally distant scaffolds, so they do not outweigh the convergent low-F evidence. Therefore predict low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Several high-transfer records are qualitative ('low', 'very low') rather than exact F values.",
    "Some artemisinin-block records refer to artesunate/dihydroartemisinin rather than artemisinin itself, adding uncertainty.",
    "The baicalin record's associated SMILES appears inconsistent with baicalin, reducing confidence in that specific transfer.",
    "No permeability, transporter, or metabolism data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

